function brandGlyph(name: string): { paths: readonly string[]; evenodd: boolean } | null {
  const brand = GLYPH_ALIASES[name.toLowerCase()];
  if (!brand) return null;
  return { paths: GLYPH_PATHS[brand], evenodd: EVENODD_GLYPHS.has(brand) };
}

/** One- or two-letter monogram from a name's leading tokens. */
function monogram(name: string): string {
  const tokens = name.split(/[\s_-]+/).filter(Boolean);
  if (tokens.length === 0) return '?';
  if (tokens.length === 1) return tokens[0].slice(0, 1).toUpperCase();
  return (tokens[0].slice(0, 1) + tokens[1].slice(0, 1)).toUpperCase();
}

/* The tile background stays neutral (in this dashboard color carries
 * semantics, and family identity is shape), while the mark itself is inked
 * in the theme's brand accent - blue in the light palette, gold in the
 * dark one - so the tiles read as part of the brand rather than greyed out. */
const Tile = styled.span`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: ${({ theme }) => theme.radii.md};
  background: ${({ theme }) => theme.colors.surfaceSunken};
  border: 1px solid ${({ theme }) => theme.colors.borderLight};
  color: ${({ theme }) => theme.colors.gold};
  font-family: ${({ theme }) => theme.fonts.body};
  font-size: ${({ theme }) => theme.fontSizes.sm};
  font-weight: 700;
  letter-spacing: 0.5px;
`;

/** Render the brand mark (vector or bundled raster) or monogram tile. */
export function FamilyAvatar({ name, markCandidates }: FamilyAvatarProps) {
  for (const candidate of [...(markCandidates ?? []), name]) {
    const key = candidate.toLowerCase();
    const raster = RASTER_ALIASES[key];
    if (raster) {
      return (
        <Tile aria-hidden title={candidate}>
          <img src={RASTER_MARKS[raster]} width={24} height={24} alt="" />
        </Tile>
      );
    }
    const glyph = brandGlyph(candidate);
    if (glyph) {
      return (
        <Tile aria-hidden title={candidate}>
          <svg
            width={20}
            height={20}
            viewBox="0 0 24 24"
            fill="currentColor"
            fillRule={glyph.evenodd ? 'evenodd' : undefined}
            clipRule={glyph.evenodd ? 'evenodd' : undefined}
          >
            {glyph.paths.map((d) => <path key={d.slice(0, 16)} d={d} />)}
          </svg>
        </Tile>
      );
    }
  }
  return <Tile aria-hidden title={name}>{monogram(name)}</Tile>;
}
